"""EPIC protocol laboratory.

The program intentionally keeps the replay engine and the finite graph
algorithms separate.  In particular, the latter uses the complete graph when
computing enabledness, even while looking for a cycle in a subgraph.
"""
import json
import re
import sys
from collections import deque


class Failure(Exception):
    def __init__(self, code):
        self.code = code


class BadJSON(Exception):
    pass


_NAME = re.compile(r"[A-Za-z][A-Za-z0-9_]{0,63}\Z")
SNAP_MIN = -(1 << 60)
SNAP_MAX = 1 << 60
INPUT_MIN = -1000000000
INPUT_MAX = 1000000000


def schema():
    raise Failure("E_SCHEMA")


def limit():
    raise Failure("E_LIMIT")


def is_int(x):
    return type(x) is int


def integer(x, lo=None, hi=None):
    if not is_int(x):
        schema()
    if lo is not None and x < lo:
        limit()
    if hi is not None and x > hi:
        limit()
    return x


def name(x):
    if not isinstance(x, str):
        schema()
    if len(x) > 64:
        limit()
    # The regular expression also excludes non-ASCII characters.
    if _NAME.fullmatch(x) is None:
        schema()
    return x


def exact_object(x, keys):
    if not isinstance(x, dict) or set(x) != set(keys):
        schema()


def validate_inputs(x):
    """Validate the common rank-major array and return (P,R,D)."""
    if not isinstance(x, list):
        schema()
    p = len(x)
    if p < 1 or p > 8:
        limit()
    if not all(isinstance(row, list) for row in x):
        schema()
    rcount = len(x[0])
    if rcount > 128:
        limit()
    if any(len(row) != rcount for row in x):
        schema()
    if rcount == 0:
        # D is defined to be zero in this case.
        return p, 0, 0
    if not all(isinstance(v, list) for row in x for v in row):
        schema()
    d = len(x[0][0])
    if d > 32:
        limit()
    for row in x:
        for vec in row:
            if len(vec) != d:
                schema()
            for z in vec:
                integer(z, INPUT_MIN, INPUT_MAX)
    return p, rcount, d


def expected_results(inputs, p, rcount, d):
    ans = [[0] * d for _ in range(rcount)]
    for r in range(p):
        row = inputs[r]
        for q in range(rcount):
            src = row[q]
            dst = ans[q]
            for k in range(d):
                dst[k] += src[k]
    return ans


def validate_replay(obj):
    exact_object(obj, ("op", "inputs", "slots", "window", "events"))
    p, rcount, d = validate_inputs(obj["inputs"])
    slots = integer(obj["slots"], 1, 16)
    window = integer(obj["window"], 1, slots)
    events = obj["events"]
    if not isinstance(events, list):
        schema()
    if len(events) > 20000:
        limit()
    # Validate the complete event list before doing any stateful processing.
    for ev in events:
        if not isinstance(ev, list) or not ev:
            schema()
        kind = ev[0]
        if not isinstance(kind, str):
            schema()
        if kind == "send":
            if len(ev) != 3:
                schema()
            integer(ev[1], 0, p - 1)
            integer(ev[2], 0, rcount - 1)
        elif kind == "retry":
            if len(ev) != 2:
                schema()
            integer(ev[1], 0, p - 1)
        elif kind == "deliver" or kind == "drop" or kind == "duplicate":
            if len(ev) != 2:
                schema()
            integer(ev[1], 0, 200000)
        else:
            schema()
    return p, rcount, d, slots, window, events


def replay(obj):
    p, rcount, d, slot_count, window, events = validate_replay(obj)
    inputs = obj["inputs"]

    sent = [0] * p
    received = [[] for _ in range(p)]
    up_next = [0] * p
    acked = [0] * p
    floor = 0
    # Each item is [absolute sequence, set of ranks, vector sum], or None.
    buf = [None] * slot_count
    pending = {}
    next_id = 0
    event_answer = []

    def create(kind, rank, seq, value):
        nonlocal next_id
        if next_id >= 200000:
            limit()
        pid = next_id
        next_id += 1
        # Copies at creation make the immutability of packets explicit.  No
        # operation mutates a packet value afterwards.
        if value is not None:
            value = list(value)
        pending[pid] = [pid, kind, rank, seq, value]
        if len(pending) > 2048:
            limit()
        return pid

    for ev in events:
        kind = ev[0]
        made = []
        if kind == "send":
            rank, q = ev[1], ev[2]
            if not (sent[rank] <= q < min(rcount, sent[rank] + window)):
                event_answer.append({"status": "disabled", "created": []})
                continue
            made.append(create("up", rank, q, inputs[rank][q]))
        elif kind == "retry":
            rank = ev[1]
            full = []
            for ent in buf:
                if ent is not None and len(ent[1]) == p and ent[0] >= acked[rank]:
                    full.append(ent)
            full.sort(key=lambda ent: ent[0])
            for ent in full:
                made.append(create("down", rank, ent[0], ent[2]))
        else:
            pid = ev[1]
            packet = pending.get(pid)
            if packet is None:
                event_answer.append({"status": "missing", "created": []})
                continue
            if kind == "duplicate":
                # Duplication retains the original packet.
                made.append(create(packet[1], packet[2], packet[3], packet[4]))
            else:
                # Both delivery and drop remove the original before any
                # resulting packets are made.
                del pending[pid]
                if kind == "drop":
                    pass
                else:
                    _, pkind, rank, seq, value = packet
                    if pkind == "up":
                        q = seq
                        became_full = False
                        ent = None
                        if floor <= q < floor + slot_count:
                            ix = q % slot_count
                            ent = buf[ix]
                            if ent is None:
                                ent = [q, set(), [0] * d]
                                buf[ix] = ent
                            # Valid replay states have at most one tag per
                            # physical slot.  The tag check is important for
                            # old packets after reuse.
                            if ent[0] != q:
                                # This cannot arise from the specified
                                # transition relation; retaining the old tag
                                # is safer than ever aliasing a contribution.
                                ent = None
                            else:
                                was_full = len(ent[1]) == p
                                if rank not in ent[1]:
                                    ent[1].add(rank)
                                    src = value
                                    dst = ent[2]
                                    for k in range(d):
                                        dst[k] += src[k]
                                became_full = (not was_full) and len(ent[1]) == p
                            # Advance only through entries carrying this
                            # rank, using absolute tags rather than just the
                            # physical index.
                            while True:
                                nq = up_next[rank]
                                e2 = buf[nq % slot_count]
                                if e2 is None or e2[0] != nq or rank not in e2[1]:
                                    break
                                up_next[rank] = nq + 1
                        made.append(create("uack", rank, up_next[rank], None))
                        if became_full:
                            for dst_rank in range(p):
                                made.append(create("down", dst_rank, ent[0], ent[2]))
                    elif pkind == "uack":
                        if seq > sent[rank]:
                            sent[rank] = seq
                    elif pkind == "down":
                        if seq == len(received[rank]):
                            received[rank].append(list(value))
                        made.append(create("dack", rank, len(received[rank]), None))
                    else:  # dack
                        if seq > acked[rank]:
                            acked[rank] = seq
                        new_floor = min(acked)
                        floor = new_floor
                        if new_floor:
                            for ix, ent in enumerate(buf):
                                if ent is not None and ent[0] < new_floor:
                                    buf[ix] = None
        event_answer.append({"status": "ok", "created": made})

    hosts = [{"sent": sent[r], "received": received[r]} for r in range(p)]
    slot_answer = []
    for ent in sorted((e for e in buf if e is not None), key=lambda e: e[0]):
        slot_answer.append({"seq": ent[0], "ranks": sorted(ent[1]), "sum": ent[2]})
    packet_answer = []
    for pid in sorted(pending):
        _, pkind, rank, seq, value = pending[pid]
        packet_answer.append({"id": pid, "kind": pkind, "rank": rank,
                              "seq": seq, "value": value})
    return {"hosts": hosts, "floor": floor, "slots": slot_answer,
            "packets": packet_answer, "events": event_answer}


def validate_graph(obj):
    exact_object(obj, ("op", "inputs", "states", "edges", "start", "fairness"))
    inputs = obj["inputs"]
    p, rcount, d = validate_inputs(inputs)
    states = obj["states"]
    edges = obj["edges"]
    fairness = obj["fairness"]
    if not isinstance(states, list):
        schema()
    if len(states) < 1 or len(states) > 12000:
        limit()
    if not isinstance(edges, list):
        schema()
    if len(edges) > 60000:
        limit()
    if not isinstance(fairness, list):
        schema()
    if len(fairness) > 16:
        limit()
    start = integer(obj["start"], 0, len(states) - 1)

    expected = expected_results(inputs, p, rcount, d)
    safe_nodes = []
    done_nodes = []
    for st in states:
        exact_object(st, ("delivered", "slots"))
        delivered = st["delivered"]
        if not isinstance(delivered, list) or len(delivered) != p:
            schema()
        is_done = True
        is_safe = True
        for r in range(p):
            dl = delivered[r]
            if not isinstance(dl, list):
                schema()
            if len(dl) > rcount:
                limit()
            if len(dl) != rcount:
                is_done = False
            for q, vec in enumerate(dl):
                if not isinstance(vec, list) or len(vec) != d:
                    schema()
                for z in vec:
                    integer(z, SNAP_MIN, SNAP_MAX)
                if vec != expected[q]:
                    is_safe = False
        slots = st["slots"]
        if not isinstance(slots, list):
            schema()
        if len(slots) > 16:
            limit()
        seen_seq = set()
        for sl in slots:
            exact_object(sl, ("seq", "ranks", "sum"))
            q = integer(sl["seq"], 0, rcount - 1)
            if q in seen_seq:
                schema()
            seen_seq.add(q)
            ranks = sl["ranks"]
            if not isinstance(ranks, list):
                schema()
            if len(ranks) > p:
                # With valid unique rank indices this is also a collection
                # bound; duplicate entries are diagnosed below as schema.
                # Do not reject before checking the entries.
                pass
            seen_ranks = set()
            for r in ranks:
                integer(r, 0, p - 1)
                if r in seen_ranks:
                    schema()
                seen_ranks.add(r)
            if len(ranks) > p:
                limit()
            vec = sl["sum"]
            if not isinstance(vec, list) or len(vec) != d:
                schema()
            for z in vec:
                integer(z, SNAP_MIN, SNAP_MAX)
            want = [0] * d
            for r in ranks:
                src = inputs[r][q]
                for k in range(d):
                    want[k] += src[k]
            if vec != want:
                is_safe = False
        safe_nodes.append(is_safe)
        done_nodes.append(is_done)

    # Names are collected before assigning their export indices.
    all_names = set()
    parsed_edges = []
    triples = set()
    for eid, edge in enumerate(edges):
        if not isinstance(edge, list) or len(edge) != 3:
            schema()
        s = integer(edge[0], 0, len(states) - 1)
        a = name(edge[1])
        t = integer(edge[2], 0, len(states) - 1)
        triple = (s, a, t)
        if triple in triples:
            schema()
        triples.add(triple)
        all_names.add(a)
        parsed_edges.append((s, a, t))
    parsed_fair = []
    fair_names = set()
    for f in fairness:
        exact_object(f, ("action", "mode"))
        a = name(f["action"])
        mode = f["mode"]
        if not isinstance(mode, str) or mode not in ("weak", "strong"):
            schema()
        if a in fair_names:
            schema()
        fair_names.add(a)
        all_names.add(a)
        parsed_fair.append((a, mode))
    if len(all_names) > 64:
        limit()

    names = sorted(all_names)
    action_ids = {a: i for i, a in enumerate(names)}
    n = len(states)
    out = [[] for _ in range(n)]
    rev = [[] for _ in range(n)]
    edge_rows = []
    for eid, (s, a, t) in enumerate(parsed_edges):
        ai = action_ids[a]
        edge_rows.append((s, ai, t))
        out[s].append((t, ai, eid))
        rev[t].append((s, ai, eid))
    fair_ids = [(action_ids[a], mode) for a, mode in parsed_fair]
    return {
        "inputs": inputs, "p": p, "r": rcount, "d": d,
        "states": states, "n": n, "start": start,
        "safe_nodes": safe_nodes, "done_nodes": done_nodes,
        "names": names, "action_ids": action_ids,
        "edges": edge_rows, "out": out, "rev": rev,
        "fairness": fair_ids,
    }


def reconstruct(target, start, parent, parent_edge):
    ans = []
    while target != start:
        ans.append(parent_edge[target])
        target = parent[target]
    ans.reverse()
    return ans


def reachable_parents(start, out, forbidden=None):
    n = len(out)
    parent = [-2] * n
    parent_edge = [-1] * n
    if forbidden is not None and forbidden[start]:
        return parent, parent_edge
    parent[start] = -1
    queue = deque([start])
    while queue:
        v = queue.popleft()
        for t, _a, eid in out[v]:
            if parent[t] == -2 and (forbidden is None or not forbidden[t]):
                parent[t] = v
                parent_edge[t] = eid
                queue.append(t)
    return parent, parent_edge


def strongly_connected(vertices, out, rev, enabled, fair_bits, all_fair):
    """Iterative Kosaraju, plus fairness summaries for every component.

    A result item is (vertices, internal_edge_mask, enabled_mask,
    disabled_mask).  The masks concern declared fairness actions only.
    """
    allowed = set(vertices)
    seen = set()
    order = []
    for root in vertices:
        if root in seen:
            continue
        seen.add(root)
        stack = [(root, 0)]
        while stack:
            v, ix = stack[-1]
            av = out[v]
            if ix < len(av):
                t = av[ix][0]
                stack[-1] = (v, ix + 1)
                if t in allowed and t not in seen:
                    seen.add(t)
                    stack.append((t, 0))
            else:
                order.append(v)
                stack.pop()

    which = {}
    components = []
    for root in reversed(order):
        if root in which:
            continue
        cid = len(components)
        which[root] = cid
        vs = []
        stack = [root]
        while stack:
            v = stack.pop()
            vs.append(v)
            for u, _a, _eid in rev[v]:
                if u in allowed and u not in which:
                    which[u] = cid
                    stack.append(u)
        components.append(vs)

    nc = len(components)
    edge_masks = [0] * nc
    enabled_masks = [0] * nc
    disabled_masks = [0] * nc
    for v in vertices:
        cid = which[v]
        ev = enabled[v]
        enabled_masks[cid] |= ev
        disabled_masks[cid] |= all_fair & ~ev
        for t, a, _eid in out[v]:
            if which.get(t) == cid:
                edge_masks[cid] |= fair_bits[a]
    return [(components[i], edge_masks[i], enabled_masks[i], disabled_masks[i])
            for i in range(nc)]


def fair_witness(root_comp, out, rev, enabled, fair_bits, weak_mask,
                 strong_mask, all_fair, prefix_parent, prefix_edge, start):
    """Build a closed walk covering all fairness witnesses in an SCC."""
    vs, edge_mask, _enabled_or, _disabled = root_comp
    comp_set = set(vs)
    root = vs[0]

    # An internal edge is the occurrence witness for every declared action
    # which has one.  A weak action without such an edge needs a disabled
    # state instead.  Strong actions without an internal edge have no enabled
    # state in a candidate component.
    need_edges = edge_mask & all_fair
    need_vertices = weak_mask & ~edge_mask
    edge_witness = {}
    vertex_witness = {}
    for v in vs:
        missing = need_vertices & ~enabled[v]
        while missing:
            bit = missing & -missing
            vertex_witness[bit] = v
            missing ^= bit
        for t, a, eid in out[v]:
            bit = fair_bits[a]
            if bit and (bit & need_edges) and bit not in edge_witness and t in comp_set:
                edge_witness[bit] = (v, t, eid)

    # Trees from and to the root let us include each witness without an
    # O(VE) closed-walk construction.  There are at most sixteen witnesses.
    parent = {root: -1}
    parent_e = {}
    queue = deque([root])
    while queue:
        v = queue.popleft()
        for t, _a, eid in out[v]:
            if t in comp_set and t not in parent:
                parent[t] = v
                parent_e[t] = eid
                queue.append(t)
    next_node = {root: -1}
    next_e = {}
    queue = deque([root])
    while queue:
        v = queue.popleft()
        for u, _a, eid in rev[v]:
            if u in comp_set and u not in next_node:
                next_node[u] = v
                next_e[u] = eid
                queue.append(u)

    def from_root(v):
        ids = []
        while v != root:
            ids.append(parent_e[v])
            v = parent[v]
        ids.reverse()
        return ids

    def to_root(v):
        ids = []
        while v != root:
            ids.append(next_e[v])
            v = next_node[v]
        return ids

    loop = []
    # Sorting by bit is immaterial semantically and makes output stable.
    for bit in sorted(edge_witness):
        u, v, eid = edge_witness[bit]
        loop.extend(from_root(u))
        loop.append(eid)
        loop.extend(to_root(v))
    for bit in sorted(vertex_witness):
        v = vertex_witness[bit]
        loop.extend(from_root(v))
        loop.extend(to_root(v))
    if not loop:
        # This is exactly the case where an implicit stutter at the root is a
        # fair nonempty cycle (all needed weak witnesses, if any, are at the
        # root and no strong action needs an occurrence).
        loop = [-1]
    prefix = reconstruct(root, start, prefix_parent, prefix_edge)
    return {"prefix": prefix, "loop": loop}


def audit(graph):
    n = graph["n"]
    start = graph["start"]
    out = graph["out"]
    rev = graph["rev"]
    safe_nodes = graph["safe_nodes"]
    done_nodes = graph["done_nodes"]

    # Safety is unrestricted reachability, including paths through done and
    # unsafe states.  Keep the first BFS unsafe witness.
    parent, parent_edge = reachable_parents(start, out)
    unsafe = None
    for v in range(n):
        if parent[v] != -2 and not safe_nodes[v]:
            unsafe = v
            break
    is_safe = unsafe is None
    safety = None if is_safe else {"prefix": reconstruct(unsafe, start, parent, parent_edge)}

    # A done initial state already satisfies <>Done on every path.
    if done_nodes[start]:
        return {"safe": is_safe, "safety": safety, "terminates": True, "liveness": None}

    # Counterexample reachability may not pass through a done state.
    lp, le = reachable_parents(start, out, done_nodes)
    live_vertices = [v for v in range(n) if lp[v] != -2]
    fairness = graph["fairness"]
    fcount = len(fairness)
    all_fair = (1 << fcount) - 1
    fair_bits = [0] * len(graph["names"])
    weak_mask = 0
    strong_mask = 0
    for bit_no, (aid, mode) in enumerate(fairness):
        bit = 1 << bit_no
        fair_bits[aid] = bit
        if mode == "weak":
            weak_mask |= bit
        else:
            strong_mask |= bit
    enabled = [0] * n
    for v in range(n):
        mask = 0
        for _t, a, _eid in out[v]:
            mask |= fair_bits[a]
        enabled[v] = mask

    # A stutter-only cycle is fair exactly when no declared action is enabled
    # at its sole state.  This also handles graphs with no explicit edges.
    if all_fair:
        for v in live_vertices:
            if enabled[v] == 0:
                return {"safe": is_safe, "safety": safety, "terminates": False,
                        "liveness": {"prefix": reconstruct(v, start, lp, le), "loop": [-1]}}
    else:
        v = live_vertices[0]
        return {"safe": is_safe, "safety": safety, "terminates": False,
                "liveness": {"prefix": reconstruct(v, start, lp, le), "loop": [-1]}}

    # Fair-cycle search.  Weak fairness is a generalized Buechi condition:
    # each weak action needs an internal occurrence or a disabled state.  For
    # strong fairness, if an SCC has an enabled state but no internal
    # occurrence, every fair cycle in it must avoid all those enabled states.
    # Removing them and recomputing SCCs is the standard exact Streett SCC
    # refinement; it deliberately does not use enabledness from the pruned
    # graph.
    work = strongly_connected(live_vertices, out, rev, enabled, fair_bits, all_fair)
    while work:
        comp = work.pop()
        vs, edge_mask, enabled_or, disabled_mask = comp
        if weak_mask & ~(edge_mask | disabled_mask):
            continue
        bad = strong_mask & enabled_or & ~edge_mask
        if bad:
            bit = bad & -bad
            remaining = [v for v in vs if not (enabled[v] & bit)]
            if remaining:
                work.extend(strongly_connected(remaining, out, rev, enabled,
                                                fair_bits, all_fair))
            continue
        witness = fair_witness(comp, out, rev, enabled, fair_bits, weak_mask,
                               strong_mask, all_fair, lp, le, start)
        return {"safe": is_safe, "safety": safety, "terminates": False,
                "liveness": witness}

    return {"safe": is_safe, "safety": safety, "terminates": True, "liveness": None}


def tla_set(items):
    return "{" + ",".join(str(x) for x in items) + "}"


def export_graph(graph):
    names = graph["names"]
    aids = graph["action_ids"]
    # String literals need no escaping: action names are ASCII alphanumeric
    # and underscores by schema.
    action_tuple = "<<" + ",".join('"' + a + '"' for a in names) + ">>"
    triples = ["<<%d,%d,%d>>" % (s, a + 1, t) for s, a, t in graph["edges"]]
    wf = []
    sf = []
    for aid, mode in graph["fairness"]:
        (wf if mode == "weak" else sf).append(aid + 1)
    safe = [i for i, yes in enumerate(graph["safe_nodes"]) if yes]
    done = [i for i, yes in enumerate(graph["done_nodes"]) if yes]
    lines = [
        "---- MODULE ModelData ----",
        "EXTENDS Integers, Sequences, FiniteSets",
        "Nodes == 0..%d" % (graph["n"] - 1),
        "Initial == %d" % graph["start"],
        "Edges == " + tla_set(triples),
        "ActionNames == " + action_tuple,
        "WFIds == " + tla_set(wf),
        "SFIds == " + tla_set(sf),
        "SafeNodes == " + tla_set(safe),
        "DoneNodes == " + tla_set(done),
        "====",
    ]
    module = "\n".join(lines) + "\n"
    config = "SPECIFICATION Spec\nINVARIANT Safety\nPROPERTY Termination\nCHECK_DEADLOCK FALSE\n"
    return {"module": module, "config": config}


def handle(obj):
    if not isinstance(obj, dict):
        schema()
    if "op" not in obj or "inputs" not in obj:
        schema()
    op = obj["op"]
    if not isinstance(op, str):
        schema()
    if op == "replay":
        return replay(obj)
    if op == "audit" or op == "export":
        graph = validate_graph(obj)
        if op == "audit":
            return audit(graph)
        return export_graph(graph)
    schema()


def object_pairs(pairs):
    ans = {}
    for k, v in pairs:
        if k in ans:
            raise BadJSON()
        ans[k] = v
    return ans


def bad_constant(_s):
    raise BadJSON()


def process_line(raw):
    # sys.stdin.buffer iteration includes the LF, but no other line ending is
    # removed before enforcing the 32 MiB line bound.
    content = raw[:-1] if raw.endswith(b"\n") else raw
    if len(content) > 32 * 1024 * 1024:
        return {"error": "E_LIMIT"}
    try:
        text = content.decode("utf-8", "strict")
        obj = json.loads(text, object_pairs_hook=object_pairs,
                         parse_constant=bad_constant)
    except (UnicodeDecodeError, json.JSONDecodeError, BadJSON, RecursionError, ValueError):
        return {"error": "E_JSON"}
    try:
        return handle(obj)
    except Failure as exc:
        return {"error": exc.code}
    except Exception:
        # Malformed input must never produce a traceback on stdout.  All
        # expected data-dependent failures are Failure instances above.
        return {"error": "E_SCHEMA"}


def main():
    # Valid numeric fields are small, but JSON itself can contain a long
    # integer token.  Let the normal field range checks classify it rather
    # than leaking Python's implementation digit-limit exception.
    try:
        sys.set_int_max_str_digits(0)
    except AttributeError:
        pass
    output = sys.stdout.buffer
    for raw in sys.stdin.buffer:
        ans = process_line(raw)
        text = json.dumps(ans, ensure_ascii=True, separators=(",", ":"))
        output.write(text.encode("utf-8"))
        output.write(b"\n")


if __name__ == "__main__":
    main()
